Translate("ptBR", "ironforge", {
	title = "Altaforja",
	aliases = { "cidade de Altaforja" },
	sections = {
		{
			title = "Resumo",
			text = [=[Altaforja é a capital do {link:kingdom-of-ironforge}Reino de Altaforja{/link} e a cidade mais antiga dos {link:dwarves}anões{/link}. Ela foi escavada no coração de uma montanha em {link:dun-morogh}Dun Morogh{/link}, e nem mesmo a {link:horde}Horda{/link}, no auge de seu poder, conseguiu tomá-la. Em seu centro, os fogos da {link:the-great-forge}Great Forge{/link} ardem dia e noite, e os rios de metal derretido que os alimentam iluminam a cidade inteira de vermelho e dourado. Ao redor da forja ficam os salões do comércio, do saber, da magia e da guerra, e sob o trono ficam salões ainda mais antigos.]=],
		},
		{
			title = "Origens",
			text = [=[Os anões afirmam que Altaforja é seu primeiro lar e que seu povo foi moldado da pedra destas montanhas em eras passadas. Nenhuma crônica registra o ano em que seus primeiros salões foram talhados. Por longas eras, todos os anões foram governados de Altaforja por um único grande rei. Quando ele morreu, os clãs Bronzebeard, Martelo Feroz e Ferro Negro lutaram por seu trono. Os Bronzebeard mantiveram a cidade e, quando os {link:dark-iron-dwarves}Ferro Negro{/link} voltaram para tomá-la, foram destroçados diante de seus portões.]=],
		},
		{
			title = "Nos Dias de Hoje",
			text = [=[O Rei {link:magni-bronzebeard}Magni Bronzebeard{/link} governa do {link:high-seat}High Seat{/link}, com o Senado de Altaforja a seu lado, e nem sempre de acordo com ele. Boa parte de seu exército está longe, a serviço da {link:alliance}Aliança{/link}. Seu irmão {link:muradin-bronzebeard}Muradin Bronzebeard{/link} se perdeu no norte, e seu irmão {link:brann-bronzebeard}Brann Bronzebeard{/link} percorre o mundo. Sua filha Moira desapareceu, e ele acredita que o imperador {link:dark-iron-dwarves}Ferro Negro{/link} a levou. Os gnomos de {link:gnomeregan}Gnomeregan{/link} vivem em {link:tinker-town}Tinker Town{/link} desde que sua cidade caiu, e seus engenhoqueiros enchem os salões de barulho. Agora os velhos caminhos selados sob o High Seat foram abertos. Algo vem perturbando as tumbas dos thanes, e os Ferro Negro foram encontrados cavando em direção a elas.]=],
		},
		{
			title = "Habitantes",
			text = [=[• {b}Os anões Bronzebeard.{/b} Ferreiros, mercadores, soldados, sacerdotes e estudiosos enchem os distritos da cidade.
• {b}Os {link:gnomeregan-exiles}Exilados de Gnomeregan{/link}.{/b} O Grão-Engenhoqueiro {link:gelbin-mekkatorque}Gelbin Mekkatorque{/link} lidera seu povo a partir de {link:tinker-town}Tinker Town{/link}.
• {b}A Liga dos Exploradores.{/b} Do {link:hall-of-explorers}Hall of Explorers{/link}, a {link:explorers-league}Liga dos Exploradores{/link} envia seus membros a ruínas por todo o mundo.
• {b}Viajantes da {link:alliance}Aliança{/link}.{/b} {link:humans}Humanos{/link} vêm e vão pelo metrô gnômico que parte de {link:stormwind-city}Ventobravo{/link}.
• {b}Ladrões na escuridão.{/b} Na Forlorn Cavern, uma sociedade chamada Círculo Oculto conspira para tomar uma parte das riquezas do rei.]=],
		},
		{
			title = "História",
			text = [=[• {b}Os Três Martelos.{/b} Os Bronzebeard defenderam Altaforja contra os próprios parentes. Uma tábua de tratado guardada nos cofres reais registra a paz que se seguiu: assinada pelos Bronzebeard e pelos Martelo Feroz, e nunca pelos {link:dark-iron-dwarves}Ferro Negro{/link}.
• {b}A {link:second-war}Segunda Guerra{/link}.{/b} A {link:horde}Horda{/link} invadiu Khaz Modan, mas Altaforja resistiu. Os anões se juntaram à {link:alliance}Aliança de Lordaeron{/link} e lutaram até que a Horda fosse derrotada.
• {b}A {link:third-war}Terceira Guerra{/link}.{/b} {link:muradin-bronzebeard}Muradin{/link} foi para Nortúndria e não voltou. Os anões o contam entre os mortos.
• {b}A Queda de {link:gnomeregan}Gnomeregan{/link}.{/b} Quando os gnomos perderam sua cidade, {link:magni-bronzebeard}Magni{/link} abriu Altaforja para eles.
• {b}Nos Dias de Hoje.{/b} Os salões sob {link:high-seat}o High Seat{/link} estão abertos de novo, e o reino descobre que seu inimigo mais antigo vem cavando em direção aos seus mortos mais antigos.]=],
		},
		{
			title = "Saber da Montanha",
			text = [=[• Um pedreiro de Altaforja esculpiu um memorial para Sully Balloo, um soldado que morreu longe de casa, em pedra fina trazida da {link:lordaeron}Lordaeron{/link} arruinada. O próprio rei pagou por ele.
• Os montanheses que morrem nas neves de {link:dun-morogh}Dun Morogh{/link} voltam para casa como rifles, com seus nomes gravados nas coronhas.]=],
		},
	},
})

Translate("ptBR", "the-great-forge", {
	title = "Great Forge",
	aliases = { "a Great Forge" },
	sections = {
		{
			title = "Resumo",
			text = [=[A Great Forge ocupa o salão central de {link:ironforge}Altaforja{/link}. Metal derretido despeja das alturas em grandes bacias e, ao redor delas, os ferreiros da cidade trabalham em bigornas que nunca esfriam. O calor e a luz da forja chegam a todos os distritos, e suas marteladas são o som que os anões chamam de lar. Comerciantes, instrutores e mensageiros lotam seu anel, e os grifos da cidade vêm e vão do terraço próximo. Nenhum outro lugar da cidade é tão movimentado, e nenhum é tão amado.]=],
		},
	},
})

Translate("ptBR", "the-commons", {
	title = "The Commons",
	sections = {
		{
			title = "Resumo",
			text = [=[The Commons é o distrito do comércio de {link:ironforge}Altaforja{/link}. Aqui ficam o Cofre de Altaforja, onde as riquezas da cidade e de seus visitantes são guardadas sob vigilância, a grande casa de leilões e a estalagem do Estalajadeiro Firebrew. Mercadores de todos os povos da {link:alliance}Aliança{/link} vêm para cá, e o distrito ressoa com pechinchas da primeira à última hora. Viajantes que passaram muito tempo na estrada vêm à estalagem em busca de uma lareira quente e de uma cerveja forte antes de seguir viagem.]=],
		},
	},
})

Translate("ptBR", "hall-of-explorers", {
	title = "Hall of Explorers",
	aliases = { "Assembleia dos Exploradores" },
	sections = {
		{
			title = "Resumo",
			text = [=[O Hall of Explorers é a sede da {link:explorers-league}Liga dos Exploradores{/link}. Suas galerias guardam relíquias trazidas de ruínas por todo o mundo, sua biblioteca mantém os livros e mapas da Liga, e seus estudiosos discutem as verdadeiras origens do povo {link:dwarves}anão{/link}. O {link:high-explorer-magellas}Grão-Explorador Magellas{/link} preside aqui. O {link:advisor-belgrum}Conselheiro Belgrum{/link}, o {link:historian-karnik}Historiador Karnik{/link} e o {link:prospector-stormpike}Prospector Stormpike{/link} cuidam de seus assuntos no salão, e as notícias dos sítios de escavação dos {link:badlands}Ermos{/link} e de {link:loch-modan}Loch Modan{/link} chegam aqui primeiro.]=],
		},
	},
})

Translate("ptBR", "tinker-town", {
	title = "Tinker Town",
	sections = {
		{
			title = "Resumo",
			text = [=[Tinker Town é o distrito que o {link:magni-bronzebeard}Rei Magni{/link} deu aos gnomos depois da queda de {link:gnomeregan}Gnomeregan{/link}. Ele retine com engrenagens e chia com vapor, e suas oficinas estão abarrotadas de engenhocas pela metade. O {link:gelbin-mekkatorque}Grão-Engenhoqueiro Mekkatorque{/link} mantém ali sua corte no exílio. De Tinker Town, o Metrô Correfundo corre nas profundezas da terra até {link:stormwind-city}Ventobravo{/link}, e os engenhoqueiros de Gnomeregan mandam voluntários de volta à cidade perdida para salvar o que puderem.]=],
		},
	},
})

Translate("ptBR", "the-mystic-ward", {
	title = "Mystic Ward",
	aliases = { "o Mystic Ward" },
	sections = {
		{
			title = "Resumo",
			text = [=[O Mystic Ward é o bairro da cidade dedicado à fé e à magia. Sacerdotes da {link:holy-light}Luz Sagrada{/link} servem no Hall of Mysteries, e magos estudam nos salões ao redor. É um lugar mais tranquilo que o resto de {link:ironforge}Altaforja{/link}, longe do rugido da forja, e quem busca as artes mais elevadas encontra ali seus mestres.]=],
		},
	},
})

Translate("ptBR", "the-military-ward", {
	title = "Military Ward",
	aliases = { "o Military Ward" },
	sections = {
		{
			title = "Resumo",
			text = [=[O Military Ward é a fortaleza dentro da fortaleza. Seu Hall of Arms treina os guerreiros de {link:ironforge}Altaforja{/link} sob Muren Stormpike, que ensina que um guerreiro nunca dá as costas a um inimigo. Os soldados do rei treinam aqui antes de marchar para as frentes da {link:alliance}Aliança{/link}. É um lugar duro, e os anões que servem nele se orgulham disso.]=],
		},
	},
})

Translate("ptBR", "high-seat", {
	title = "High Seat",
	aliases = { "o High Seat" },
	sections = {
		{
			title = "Resumo",
			text = [=[O High Seat é a sala do trono de {link:ironforge}Altaforja{/link}, erguida acima dos salões ocidentais da cidade. Aqui o {link:magni-bronzebeard}Rei Magni Bronzebeard{/link} mantém sua corte, protegido pela Guarda Real de Ferro. Senadores de Altaforja vêm e vão tratando dos assuntos do reino, e o Historiador Real guarda a memória do reino perto do trono. Uma porta ao lado do salão, selada por muito tempo, agora está aberta. Além dela, um caminho desce até {link:old-ironforge}Old Ironforge{/link}.]=],
		},
	},
})

Translate("ptBR", "old-ironforge", {
	title = "Old Ironforge",
	sections = {
		{
			title = "Resumo",
			text = [=[Old Ironforge fica sob {link:high-seat}o High Seat{/link} e é a parte mais antiga da cidade. Por gerações seus portões ficaram fechados, e poucos anões vivos haviam andado por lá. Agora o caminho está aberto. Uma longa trilha desce por velhos salões até as cavernas abaixo, onde o {link:hall-of-thanes}Hall of Thanes{/link} guarda as tumbas dos grandes anões do passado. Os guardiões dessas tumbas ouviram ruídos estranhos vindos dos cofres, e os mortos lá dentro começaram a se agitar.]=],
		},
	},
})

Translate("ptBR", "magni-bronzebeard", {
	title = "Magni Bronzebeard",
	subtitle = "Rei de Altaforja",
	found = "O High Seat, Altaforja",
	hint = "Peça uma audiência com o rei no High Seat.",
	allegiance = "Reino de Altaforja · Aliança",
	aliases = { "Magni", "Rei Magni", "Rei Magni Bronzebeard" },
	sections = {
		{
			title = "Resumo",
			text = [=[Magni Bronzebeard é o Rei de {link:ironforge}Altaforja{/link} e senhor dos anões Bronzebeard. É o mais velho de três irmãos, e a coroa mais pesada de Khaz Modan repousa sobre sua cabeça. Do {link:high-seat}High Seat{/link}, ele governa um povo orgulhoso e teimoso, negocia com um Senado que nem sempre pensa como ele e mantém a fé numa {link:alliance}Aliança{/link} que já lhe custou caro.]=],
		},
		{
			title = "Importância",
			text = [=[Magni é um dos pilares da {link:alliance}Aliança{/link}. Quando a {link:horde}Horda{/link} invadiu Khaz Modan na {link:second-war}Segunda Guerra{/link}, seu povo não esqueceu quem ficou a seu lado, e desde então {link:ironforge}Altaforja{/link} cumpre sua palavra para com a humanidade. Quando os gnomos perderam sua cidade, ele os acolheu. Quando a Aliança chama, seus soldados vão. O fardo de Magni é que cada uma dessas escolhas foi paga por seu próprio povo.]=],
		},
		{
			title = "Feitos",
			text = [=[• Lidera o {link:kingdom-of-ironforge}Reino de Altaforja{/link} e ocupa seu assento na {link:alliance}Aliança{/link}.
• Envia seu exército ao estrangeiro para lutar ao lado da Aliança, embora isso deixe suas próprias terras pouco guardadas.
• Deu aos {link:gnomeregan-exiles}exilados de Gnomeregan{/link} um lar em sua cidade.
• Chora seu irmão {link:muradin-bronzebeard}Muradin{/link}, perdido em Nortúndria. Seu irmão {link:brann-bronzebeard}Brann{/link} está longe, a serviço da Liga.
• Procura sua filha Moira, que desapareceu nas {link:burning-steppes}Estepes Ardentes{/link}, e culpa o imperador {link:dark-iron-dwarves}Ferro Negro{/link}.]=],
		},
	},
	chapters = {
		{
			title = "O Tributo de um Rei",
			hint = "Cumpra o desejo do rei para com a viúva de um soldado caído.",
			text = [=[Quando a viúva de Sully Balloo lhe escreveu, Magni não fingiu que a morte do marido dela fosse outra coisa senão uma perda. Disse que cada {link:dwarves}anão{/link} que tomba pela {link:alliance}Aliança{/link} pesa em sua alma. Não podia trazer Sully de volta, então mandou o Grão-Pedreiro esculpir para ele um memorial de granito de {link:lordaeron}Lordaeron{/link}, na esperança de que os que viessem depois lembrassem por quem tais soldados morreram.]=],
		},
		{
			title = "O Tratado de Entendimento",
			hint = "Recupere um tratado antigo dos cofres sob a cidade.",
			text = [=[Do Relicário dos Reis, sob {link:ironforge}Altaforja{/link}, veio uma tábua de pedra. Magni a reconheceu de imediato. Era a paz firmada depois da guerra dos três clãs, nos dias de seu ancestral Madoran, o primeiro Bronzebeard a governar Altaforja. Os Bronzebeard a haviam assinado, e os Martelo Feroz a haviam assinado. Os {link:dark-iron-dwarves}Ferro Negro{/link}, não.]=],
		},
		{
			title = "Sob Nossos Pés",
			hint = "Ponha fim à incursão Ferro Negro sob Altaforja.",
			text = [=[A notícia de que uma força {link:dark-iron-dwarves}Ferro Negro{/link} fora encontrada sob a cidade pegou o rei de surpresa. Ele ficou contente em saber que o comandante dela estava morto e ordenou de imediato que as brechas fossem seladas e os salões inferiores reforçados. Também mandou suas calorosas lembranças a um velho amigo Martelo Feroz, o {link:earthseer-farsen}Vidente da Terra Farsen{/link}, e a exigência de que Farsen viesse visitá-lo como se deve.]=],
		},
		{
			title = "A Princesa Perdida",
			hint = "Descubra o que foi feito da filha do rei.",
			text = [=[Magni chorou ao falar de Moira. Tinha mandado seus homens vasculharem {link:burning-steppes}as Estepes{/link} Ardentes, e a única pista que encontraram apontava para as profundezas da {link:blackrock-mountain}Rocha Negra{/link}. Ele acreditava que ela fosse prisioneira do imperador {link:dark-iron-dwarves}Ferro Negro{/link}, Dagran {link:ruins-of-thaurissan}Thaurissan{/link}, presa por seus feitiços, e queria o imperador morto. Quando a verdade chegou até ele, foi pior do que temia. Moira carregava o filho de Thaurissan e mandou dizer que o herdeiro de {link:ironforge}Altaforja{/link} seria um Ferro Negro. Magni só pôde dizer que, mesmo na morte, Thaurissan havia vencido.]=],
		},
	},
	mentions = {
		{ text = "O Tributo de um Rei" },
		{ text = "A Negociação da Paz" },
		{ text = "Kharan Mighthammer" },
		{ text = "O Portador de Más Notícias" },
		{ text = "O Destino do Reino" },
	},
	bonds = {
		{ id = "muradin-bronzebeard", name = "Muradin Bronzebeard", note = "seu irmão, perdido em Nortúndria" },
		{ id = "brann-bronzebeard", name = "Brann Bronzebeard", note = "seu irmão mais novo" },
		{ id = "gelbin-mekkatorque", name = "Gelbin Mekkatorque", note = "seu aliado e hóspede" },
		{ id = "earthseer-farsen", name = "Vidente da Terra Farsen", note = "um velho amigo Martelo Feroz" },
		{ id = "royal-historian-archesonus", name = "Historiadora Real Archesonus", note = "guarda a memória de seu reino" },
		{ id = "senator-barin-redstone", name = "Senador Barin Redstone", note = "um senador de sua corte" },
	},
})

Translate("ptBR", "muradin-bronzebeard", {
	title = "Muradin Bronzebeard",
	subtitle = "Irmão do Rei",
	found = "Perdido em Nortúndria",
	allegiance = "Reino de Altaforja",
	aliases = { "Muradin" },
	sections = {
		{
			title = "Resumo",
			text = [=[Muradin Bronzebeard é irmão do {link:magni-bronzebeard}Rei Magni{/link}. Foi um dos guerreiros mais poderosos de {link:ironforge}Altaforja{/link}, um {link:dwarves}anão{/link} de grande força, fala direta e coração caloroso. Na {link:third-war}Terceira Guerra{/link}, ele foi ao continente gelado de Nortúndria e não voltou para casa. Altaforja o conta entre seus mortos.]=],
		},
		{
			title = "Importância",
			text = [=[Muradin estava ligado à casa de {link:lordaeron}Lordaeron{/link} por mais do que uma aliança. Ele fora mestre de armas do jovem Príncipe {link:arthas-menethil}Arthas Menethil{/link}, e os dois eram amigos. Esse laço fez de Muradin testemunha dos primeiros passos do príncipe rumo à ruína. Também lhe custou a vida, ou assim se acredita em {link:ironforge}Altaforja{/link}.]=],
		},
		{
			title = "Feitos",
			text = [=[• Serviu à {link:alliance}Aliança{/link} e era conhecido nas cortes dos reinos humanos.
• Ensinou ao príncipe de {link:lordaeron}Lordaeron{/link} a arte da espada e do martelo.
• Liderou uma expedição de anões a Nortúndria em busca de uma lendária espada rúnica chamada Gélido Lamento.
• Lutou ao lado de {link:arthas-menethil}Arthas{/link} contra os mortos-vivos nos ermos gelados.]=],
		},
		{
			title = "A Jornada ao Norte",
			text = [=[A companhia de Muradin procurava Gélido Lamento em Nortúndria havia muito tempo quando encontrou {link:arthas-menethil}Arthas{/link}, que seguira um senhor do medo através do mar. Os anões e o príncipe uniram forças contra os mortos-vivos. Muradin foi ficando inquieto ao observar seu antigo pupilo. Arthas queimara os próprios navios para que seus homens não pudessem voltar para casa, e seu ódio pelo inimigo se tornara a única coisa pela qual ele parecia viver.

Por fim, encontraram a lâmina numa caverna gelada, selada no gelo e guardada. Muradin leu o aviso gravado ali e implorou a Arthas que a deixasse. O príncipe se recusou. Quando Arthas libertou a espada, o gelo explodiu, e um estilhaço dele derrubou Muradin. Arthas tomou Gélido Lamento e seguiu sem ele.]=],
		},
		{
			title = "Em Altaforja",
			text = [=[Os anões se lembram de Muradin como um herói da {link:alliance}Aliança{/link} e irmão de seu rei. Sua perda é mais um peso que {link:magni-bronzebeard}Magni{/link} carrega, ao lado de um exército longe de casa e de uma filha levada pelos {link:dark-iron-dwarves}Ferro Negro{/link}. Nos salões de {link:ironforge}Altaforja{/link}, seu nome é pronunciado com tristeza e com o orgulho teimoso que os anões guardam para os que caíram fazendo o que julgavam certo.]=],
		},
		{
			title = "Sem Registro",
			text = [=[O que foi feito de Muradin depois daquele dia não se sabe em {link:ironforge}Altaforja{/link}. Seu povo acredita que ele morreu no gelo. Nenhuma crônica conhecida pelos anões diz o contrário.]=],
		},
	},
	bonds = {
		{ id = "magni-bronzebeard", name = "Magni Bronzebeard", note = "seu irmão" },
		{ id = "brann-bronzebeard", name = "Brann Bronzebeard", note = "seu irmão" },
		{ id = "arthas-menethil", name = "Arthas Menethil", note = "seu pupilo" },
	},
})

Translate("ptBR", "brann-bronzebeard", {
	title = "Brann Bronzebeard",
	subtitle = "Explorador da Liga dos Exploradores",
	found = "Viajando longe de Altaforja",
	allegiance = "Reino de Altaforja · Liga dos Exploradores",
	aliases = { "Brann" },
	sections = {
		{
			title = "Resumo",
			text = [=[Brann Bronzebeard é o irmão mais novo do {link:magni-bronzebeard}Rei Magni{/link}. Enquanto Magni tomou a coroa e {link:muradin-bronzebeard}Muradin{/link} o martelo, Brann tomou o mapa e a lanterna. Ele é o explorador mais famoso da {link:explorers-league}Liga dos Exploradores{/link}, um {link:dwarves}anão{/link} que prefere dormir numa ruína titânica a dormir numa cama real.]=],
		},
		{
			title = "Importância",
			text = [=[Brann é o espírito vivo da grande pergunta da Liga: de onde vieram os anões? Passou a vida vasculhando os lugares antigos do mundo em busca da resposta, e seu nome abre portas que se fecharam para escavadores menores. Os estudiosos da Liga no {link:hall-of-explorers}Hall of Explorers{/link} dão continuidade a seu trabalho enquanto ele viaja.]=],
		},
		{
			title = "Feitos",
			text = [=[• Explorou ruínas por todos os {link:eastern-kingdoms}Reinos do Leste{/link} e além em busca das origens dos anões.
• É contado entre os principais membros da {link:explorers-league}Liga dos Exploradores{/link}.]=],
		},
		{
			title = "A Grande Pergunta",
			text = [=[A pergunta que move Brann é a mesma que toda a Liga faz: os anões foram mesmo moldados da pedra pelos titãs? Em sua ausência, seus colegas chegaram mais perto de uma resposta do que nunca. Das profundezas de {link:uldaman}Uldaman{/link}, trouxeram registros das obras dos titãs, e esses registros apontam para cofres ainda maiores nos desertos do sul. É o tipo de descoberta a que Brann dedicou a vida.]=],
		},
		{
			title = "Sem Registro",
			text = [=[As viagens de Brann o levaram para longe de {link:ironforge}Altaforja{/link}, e ninguém na cidade sabe dizer onde ele está agora. De suas jornadas, os salões do {link:high-seat}High Seat{/link} ouvem apenas boatos. Este registro guarda somente o que é certo.]=],
		},
	},
	bonds = {
		{ id = "magni-bronzebeard", name = "Magni Bronzebeard", note = "seu irmão mais velho" },
		{ id = "muradin-bronzebeard", name = "Muradin Bronzebeard", note = "seu irmão" },
		{ id = "high-explorer-magellas", name = "Grão-Explorador Magellas", note = "lidera a Liga em sua ausência" },
	},
})

Translate("ptBR", "gelbin-mekkatorque", {
	title = "Gelbin Mekkatorque",
	subtitle = "Grão-Engenhoqueiro, Rei dos Gnomos",
	found = "Tinker Town, Altaforja",
	hint = "Procure o Grão-Engenhoqueiro em Tinker Town.",
	allegiance = "Exilados de Gnomeregan · Aliança",
	aliases = { "Mekkatorque", "Grão-Engenhoqueiro Mekkatorque", "Gelbin", "Grão-Engenhoqueiro Gelbin Mekkatorque" },
	sections = {
		{
			title = "Resumo",
			text = [=[Gelbin Mekkatorque é o Grão-Engenhoqueiro dos gnomos, o rei de um povo que perdeu seu reino. Ele governava em {link:gnomeregan}Gnomeregan{/link} quando a cidade era grandiosa. Hoje governa de uma oficina em {link:tinker-town}Tinker Town{/link}, hóspede dos anões, com a maior parte de seu povo morta, envenenada ou dispersa. Não perdeu o juízo nem a vontade. Pretende voltar para casa.]=],
		},
		{
			title = "Importância",
			text = [=[Mekkatorque mantém os gnomos unidos. Sem ele, os exilados seriam uma multidão de refugiados. Com ele, continuam sendo uma nação, com um assento entre os povos da {link:alliance}Aliança{/link} e uma reivindicação sobre sua cidade da qual nunca abriram mão.]=],
		},
		{
			title = "Feitos",
			text = [=[• Liderou os gnomos de {link:gnomeregan}Gnomeregan{/link} como Grão-Engenhoqueiro.
• Quando os troggs se ergueram sob a cidade, voltou as próprias artes dos gnomos contra eles num expurgo desesperado, e a cidade foi envenenada.
• Levou os sobreviventes a {link:ironforge}Altaforja{/link} e fez de {link:tinker-town}Tinker Town{/link} o lar deles.
• Envia voluntários de volta a Gnomeregan para recuperar o que ficou para trás e para atacar o traidor que a domina.]=],
		},
		{
			title = "A Queda da Cidade",
			text = [=[Nenhuma crônica registra o ano em que os troggs subiram das profundezas sob {link:gnomeregan}Gnomeregan{/link}. Vieram em grande número, e a cidade não conseguiu contê-los. Mekkatorque decidiu expurgá-los com uma arma feita pelos próprios gnomos. Ela matou troggs, mas também matou muitíssimos gnomos e deixou a cidade encharcada de veneno. Muitos dos que sobreviveram foram transformados em leprosos doentes e sem juízo. O resto fugiu para as neves de {link:dun-morogh}Dun Morogh{/link}.]=],
		},
		{
			title = "A Corte no Exílio",
			text = [=[Em {link:tinker-town}Tinker Town{/link}, o povo do Grão-Engenhoqueiro não parou de trabalhar. O Mestre Engenhoqueiro Overspark espera consertar seu pobre Techbot, cuja mente foi invertida na queda. O Mestre Mecânico Castpipe organiza grupos para recuperar registros vitais dos terminais da cidade. Klockmort Spannerspan precisa das peças que ninguém se lembrou de levar na fuga. Cada uma dessas missões é um pequeno passo de volta a {link:gnomeregan}Gnomeregan{/link}, e Mekkatorque incentiva todas.]=],
		},
	},
	chapters = {
		{
			title = "A Grande Traição",
			hint = "Derrube o traidor que governa Gnomeregan.",
			text = [=[Mekkatorque confiara em {link:mekgineer-thermaplugg}Sicco Thermaplugg{/link}. Nunca imaginara que Thermaplugg trairia a ele e a todo o povo {link:gnomes}gnomo{/link}, e ainda não entende por quê, pois poder e riqueza teriam chegado a Thermaplugg com o tempo. Agora o traidor está sentado nas ruínas, rei de nada. Quando chegou a notícia de que Thermaplugg havia caído, Mekkatorque se permitiu uma piada sombria e depois voltou o pensamento para o dia em que os gnomos retomariam sua cidade.]=],
		},
	},
	mentions = {
		{ text = "Resgate de Dados" },
		{ text = "Salve o Cérebro do Techbot!" },
		{ text = "Artificiais Essenciais" },
	},
	bonds = {
		{ id = "mekgineer-thermaplugg", name = "Mecagenheiro Thermaplugg", note = "o traidor" },
		{ id = "magni-bronzebeard", name = "Magni Bronzebeard", note = "seu anfitrião e aliado" },
		{ id = "razzle-sprysprocket", name = "Razzle Sprysprocket", note = "alguém de seu povo que busca uma cura" },
	},
})

Translate("ptBR", "royal-historian-archesonus", {
	title = "Historiadora Real Archesonus",
	subtitle = "Historiadora Real de Altaforja",
	found = "O High Seat, ao lado do trono",
	hint = [=[Fale com a historiadora que guarda a memória do reino ao lado do trono.]=],
	allegiance = "Reino de Altaforja",
	aliases = { "Archesonus" },
	sections = {
		{
			title = "Resumo",
			text = [=[A Historiadora Real Archesonus guarda a memória de {link:ironforge}Altaforja{/link} ao lado do trono do {link:magni-bronzebeard}Rei Magni{/link}. Quem pedir pode ouvir dela a história do reino. O relato que ela conta com mais gravidade é o dos {link:dark-iron-dwarves}Ferro Negro{/link} e da cidade de {link:ruins-of-thaurissan}Thaurissan{/link}, que ardeu em chamas.]=],
		},
		{
			title = "Importância",
			text = [=[Archesonus é a voz do passado de {link:ironforge}Altaforja{/link}. Os anões são um povo de memória longa, e no {link:high-seat}High Seat{/link} essa memória tem uma guardiã. Seu conhecimento sobre os {link:dark-iron-dwarves}Ferro Negro{/link} se tornou urgente, pois o velho inimigo do reino está em movimento outra vez.]=],
		},
		{
			title = "Feitos",
			text = [=[• Ensina a história de {link:ironforge}Altaforja{/link} aos que vêm ao {link:high-seat}High Seat{/link}.
• Envia pesquisadores às ruínas de {link:ruins-of-thaurissan}Thaurissan{/link}, nas {link:burning-steppes}Estepes Ardentes{/link}, para ler as relíquias deixadas ali.]=],
		},
	},
	chapters = {
		{
			title = "A História de Thaurissan",
			hint = "Peça à Historiadora Real a história dos Ferro Negro.",
			text = [=[Archesonus começa muito atrás, quando os {link:dark-iron-dwarves}Ferro Negro{/link} tinham uma cidade própria. {link:ruins-of-thaurissan}Thaurissan{/link} ficava numa terra verdejante que hoje são {link:burning-steppes}as Estepes{/link} Ardentes, e naqueles dias os clãs anões estavam em guerra uns com os outros. Então uma explosão terrível a destruiu, e a terra por quilômetros ao redor foi reduzida a cinzas. O que causou a explosão, ela admite, nenhum historiador sabe dizer. Os Ferro Negro que sobreviveram entraram na montanha e recomeçaram. Das cinzas ergueu-se o Pico da {link:blackrock-mountain}Rocha Negra{/link}, e {link:the-cauldron}O Caldeirão{/link} da {link:searing-gorge}Garganta Abrasadora{/link} foi fortificado. Logo surgiram sussurros de um mal antigo que governava o reino Ferro Negro por dentro. Seu relato termina no presente. Os Ferro Negro são vistos na superfície com mais frequência a cada ano. Ergueram fortes nos {link:badlands}Ermos{/link}, enviaram grandes grupos a {link:uldaman}Uldaman{/link} e até atacaram a represa de {link:loch-modan}Loch Modan{/link}.]=],
		},
		{
			title = "As Ruínas Fumegantes",
			hint = [=[Leia as relíquias de Thaurissan e traga suas memórias para casa.]=],
			text = [=[As relíquias da cidade arruinada guardam memórias, e quem as toca as guarda também. Uma criatura de chama pura. Oito anões {link:dark-iron-dwarves}Ferro Negro{/link} num ritual. Um deles sozinho no fim, ajoelhado entre sete mortos diante de um pilar de fogo. Archesonus ouviu essas memórias e disse que explicavam muita coisa, e que havia muito mais a aprender.]=],
		},
	},
	mentions = {
		{
			text = [=[As Ruínas Fumegantes de {link:ruins-of-thaurissan}Thaurissan{/link}]=],
		},
	},
	bonds = {
		{ id = "magni-bronzebeard", name = "Magni Bronzebeard", note = "seu rei" },
	},
})

Translate("ptBR", "high-explorer-magellas", {
	title = "Grão-Explorador Magellas",
	subtitle = "Grão-Explorador da Liga dos Exploradores",
	found = "O Hall of Explorers",
	hint = "Fale com o Grão-Explorador no Hall of Explorers.",
	allegiance = "Liga dos Exploradores",
	aliases = { "Magellas" },
	sections = {
		{
			title = "Resumo",
			text = [=[O Grão-Explorador Magellas lidera a {link:explorers-league}Liga dos Exploradores{/link} a partir do {link:hall-of-explorers}Hall of Explorers{/link}. Ele é um {link:dwarves}anão{/link} ocupado e faz questão de que os visitantes saibam disso. Ainda assim, ninguém em {link:ironforge}Altaforja{/link} se empolga mais com uma descoberta verdadeira, e quando uma cai em sua mesa, sua dignidade vai pela janela.]=],
		},
		{
			title = "Importância",
			text = [=[Sob Magellas, a Liga persegue a questão que mais lhe importa: a prova de que os anões foram moldados da pedra pelos titãs, a quem os velhos registros chamam de Criadores. Ele acredita que essa prova pode estar ao alcance.]=],
		},
		{
			title = "Feitos",
			text = [=[• Dirige as expedições da Liga e recompensa, com o cofre da Liga, quem a serve.
• Estuda os {link:lore-keeper-of-norgannon}Discos de Norgannon{/link} em miniatura trazidos de {link:uldaman}Uldaman{/link}.
• Volta os olhos da Liga para {link:valley-of-the-watchers}Uldum{/link}, muito ao sul, em {link:tanaris}Tanaris{/link}.]=],
		},
	},
	chapters = {
		{
			title = "Os Discos de Platina",
			hint = "Traga à Liga um achado das profundezas de Uldaman.",
			text = [=[Quando uma cópia em miniatura dos {link:lore-keeper-of-norgannon}Discos de Norgannon{/link} foi posta diante dele, Magellas perguntou onde fora encontrada, depois perguntou de novo, e não conseguiu acreditar nas respostas. Chamou-a de o achado do século. Se os discos dissessem o que ele pensava, resolveriam de uma vez por todas a velha questão da origem dos anões.]=],
		},
		{
			title = "Uldum Chama",
			hint = "Siga os discos até os portões de Uldum e traga notícias.",
			text = [=[Os discos levaram aos portões selados de {link:valley-of-the-watchers}Uldum{/link}, onde outro vigia de pedra falou de placas que estavam faltando. Magellas concordou com seus estudiosos que a busca devia esperar até que soubessem onde procurar. Prometeu que, quando chegasse a hora, a Liga mandaria as mesmas mãos de volta a campo.]=],
		},
	},
	mentions = {
		{ text = "Os Discos de Platina" },
		{ text = "Presságios de {link:valley-of-the-watchers}Uldum{/link}" },
	},
	bonds = {
		{ id = "historian-karnik", name = "Historiador Karnik", note = "seu estudioso" },
		{ id = "brann-bronzebeard", name = "Brann Bronzebeard", note = "o explorador mais famoso da Liga" },
	},
})

