	title = "Historiador Karnik",
	subtitle = "Historiador da Liga dos Exploradores",
	found = "O Hall of Explorers",
	hint = [=[Encontre o historiador da Liga que chora seu amigo Hammertoe.]=],
	allegiance = "Liga dos Exploradores",
	aliases = { "Karnik" },
	sections = {
		{
			title = "Resumo",
			text = [=[O Historiador Karnik trabalhou com o explorador Hammertoe para encontrar os artefatos perdidos de {link:uldaman}Uldaman{/link}, até que os Shadowforge mataram Hammertoe pelo que ele sabia. Karnik ainda fala com o espírito do amigo. Ele também estuda os lugares antigos do sul e encontrou pistas sobre o {link:valley-of-the-watchers}Vale dos Vigilantes{/link}, no deserto de {link:tanaris}Tanaris{/link}.]=],
