		{ text = "Volte a {link:ironforge}Altaforja{/link}" },
	},
	bonds = {
		{ id = "advisor-belgrum", name = "Conselheiro Belgrum", note = "fala pelo rei" },
		{ id = "high-explorer-magellas", name = "Grão-Explorador Magellas", note = "seu superior" },
	},
})

Translate("ptBR", "prospector-stormpike", {
	title = "Prospector Stormpike",
	subtitle = "Prospector da Liga dos Exploradores",
	found = "O Hall of Explorers",
	hint = "Encontre o prospector de pavio curto no Hall of Explorers.",
	allegiance = "Liga dos Exploradores",
	sections = {
		{
			title = "Resumo",
			text = [=[O Prospector Stormpike supervisiona as escavações da Liga a partir do {link:hall-of-explorers}Hall of Explorers{/link} e não tem paciência para assuntos triviais. Irrita-se depressa quando uma escavação anda devagar, e mais depressa ainda quando some pólvora explosiva. Sob o mau gênio há lealdade: quando os troggs tomaram {link:uldaman}Uldaman{/link}, seu primeiro pensamento foi para o amigo {link:the-lost-dwarves}Baelog{/link} e para os anões presos atrás das linhas.]=],
		},
		{
			title = "Importância",
			text = [=[Stormpike mantém os escavadores da Liga abastecidos e suas expedições em andamento, da escavação de {link:prospector-ironband}Ironband{/link} em {link:loch-modan}Loch Modan{/link} às profundezas de {link:uldaman}Uldaman{/link}.]=],
		},
	},
	mentions = {
