		{ text = "{link:the-lost-dwarves}Os Anões Perdidos{/link}" },
	},
	bonds = {
		{ id = "high-explorer-magellas", name = "Grão-Explorador Magellas", note = "lidera a Liga" },
	},
})

Translate("ptBR", "senator-barin-redstone", {
	title = "Senador Barin Redstone",
	subtitle = "Senador de Altaforja",
	found = "O High Seat",
	hint = "Encontre o senador rabugento na corte do rei.",
