	aliases = { "Barin Redstone" },
	sections = {
		{
			title = "Resumo",
			text = [=[Barin Redstone tem assento no Senado de {link:ironforge}Altaforja{/link} e frequenta a corte do rei no {link:high-seat}High Seat{/link}. É conhecido pelo temperamento azedo. Quando chegou de {link:kharanos}Kharanos{/link} um relatório que invocava a própria autoridade do rei para um trabalho em campo, Redstone ficou indignado tanto com o autor quanto com o rei e avisou que o Senado não ficaria satisfeito.]=],
