		{ id = "magni-bronzebeard", name = "Magni Bronzebeard", note = "seu rei" },
	},
})

Translate("ptBR", "afadra-dunwall", {
	title = "Afadra Dunwall",
	subtitle = "Guardiã do Saber de Altaforja",
	found = "Old Ironforge, sob o High Seat",
	hint = [=[Procure a guardiã do saber que cuida do caminho que desce ao Hall of Thanes.]=],
	allegiance = "Reino de Altaforja",
	aliases = { "Afadra" },
	sections = {
		{
			title = "Resumo",
			text = [=[Afadra Dunwall é uma Guardiã do Saber de {link:ironforge}Altaforja{/link}, uma das guardiãs que cuidam das tumbas do {link:hall-of-thanes}Hall of Thanes{/link}. Ruídos estranhos vieram dos cofres abaixo, e os espíritos dos mortos, que dormem um sono leve, despertaram. Afadra quer que eles voltem a descansar. Também quer que os outros guardiões parem de recusar seus deveres por causa de fantasmas.]=],
		},
		{
			title = "Importância",
			text = [=[Afadra é uma das poucas que ainda guardam os mortos mais antigos de {link:ironforge}Altaforja{/link}. Seu dever se tornou perigoso.]=],
		},
	},
	mentions = {
		{ text = "Os Mortos Inquietos" },
	},
	bonds = {
		{ id = "thom-filch", name = "Thom Filch", note = "outro vigia dos cofres" },
	},
})

Translate("ptBR", "thom-filch", {
	title = "Thom Filch",
	subtitle = "Gnomo dos Cofres",
	found = "Old Ironforge, sob o High Seat",
	hint = [=[Encontre o gnomo em Old Ironforge que patrulhava onde não deveria.]=],
	allegiance = "Desconhecida",
	sections = {
		{
			title = "Resumo",
			text = [=[Thom Filch é um {link:gnomes}gnomo{/link} que estava, em suas próprias palavras, patrulhando os cofres sob {link:ironforge}Altaforja{/link} quando os {link:dark-iron-dwarves}Ferro Negro{/link} irromperam da rocha em máquinas-toupeira. Ele quer que as relíquias inestimáveis dos cofres sejam recuperadas. Chama-as de espólio, depois de heranças culturais, e promete que cada uma será catalogada e devolvida a seu lugar. Poucos que o ouvem acreditam nisso.]=],
		},
		{
			title = "Importância",
			text = [=[Thom Filch foi o primeiro a ver os {link:dark-iron-dwarves}Ferro Negro{/link} subirem aos cofres, fosse o que fosse que ele estivesse fazendo ali na hora.]=],
		},
	},
	mentions = {
		{ text = "Heranças Importantes" },
	},
	bonds = {
		{ id = "afadra-dunwall", name = "Afadra Dunwall", note = "guarda as tumbas por onde ele vagueia" },
	},
})
